// Function Overloading: Flexibility vs. Readability
class APIHandler {
public:
    // Clear Overload: Distinct types provide clear intent
    void setup(int timeoutMs);
    void setup(const std::string& configPath);

    // Subtle Overload Trade-off (Potential ambiguity/obscurity):
    // Signature differs only by subtle qualifiers (const/volatile/ref).
    // Caller may misunderstand intent of (1) vs (2).

    // (1) Mutates the input object
    void process(Settings& s);

    // (2) Reads the input object only
    void process(const Settings& s);

    // (3) Overload for optimization (move semantics)
    void process(Settings&& s);
};
